let bucketSize = 33;
onmessage = (e) => {
  const events = e.data.events;
  const buckets = [];
  for (let ev of events) {
    const idx = Math.floor(ev.ts / bucketSize);
    buckets[idx] = (buckets[idx] || 0) + 1;
  }
  postMessage({ buckets });
}
